function Topbar({ onMenu, onNotice }: { onMenu: () => void; onNotice: () => void; }) {
  return <header className={styles.topbar}><button type="button" className={styles.menuButton} onClick={onMenu} aria-label="Buka atau tutup menu"><Glyph name="menu" /></button><label className={styles.globalSearch}><Glyph name="search" /><input placeholder="Cari booking, customer, kapster, atau outlet..." aria-label="Pencarian global" /><kbd>⌘ K</kbd></label><span className={styles.topbarSpacer} /><button type="button" className={styles.bellButton} onClick={onNotice} aria-label="Lihat notifikasi"><Glyph name="bell" /><i /></button><span className={styles.headerDivider} /><Avatar person={0} size={40} /><button type="button" className={styles.profileButton}><span><strong>Andi Saputra</strong><small>Owner</small></span><span className={styles.down} aria-hidden="true"><Glyph name="chevron" size={14} /></span></button></header>;
}

export function OwnerDashboard() {
  const [view, setView] = useState<View>('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notice, setNotice] = useState('');

  useEffect(() => { if (!notice) return; const timeout = window.setTimeout(() => setNotice(''), 2600); return () => window.clearTimeout(timeout); }, [notice]);
  const content = useMemo(() => {
    const props = { notify: setNotice };
    switch (view) {
      case 'dashboard': return <Overview {...props} />;
      case 'booking': return <BookingView {...props} />;
      case 'calendar': return <CalendarView {...props} />;
      case 'transactions': return <TransactionsView {...props} />;
      case 'reports': return <ReportsView {...props} />;
      case 'outlets': return <OutletsView {...props} />;
      case 'barbers': return <BarbersView {...props} />;
      case 'services': return <ServicesView {...props} />;
      case 'customers': return <CustomersView {...props} />;
      case 'cashiers': return <CashiersView {...props} />;
      case 'settings': return <SettingsView {...props} />;
    }
  }, [view]);

  function selectView(next: View) { setView(next); setSidebarOpen(false); document.querySelector(`.${styles.workspace}`)?.scrollTo({ top: 0 }); }

  return <main className={styles.dashboardApp}><Sidebar active={view} onSelect={selectView} open={sidebarOpen} /><div className={styles.appBody}><Topbar onMenu={() => setSidebarOpen(value => !value)} onNotice={() => setNotice('Anda memiliki 4 notifikasi penting')} /><div className={styles.workspace}>{content}</div></div>{sidebarOpen && <button type="button" className={styles.sidebarBackdrop} aria-label="Tutup menu" onClick={() => setSidebarOpen(false)} />} {notice && <div className={styles.toast} role="status"><Glyph name="check" />{notice}</div>}<span className={styles.demoBadge}>DEMO · DATA DUMMY</span></main>;
}
